mt_srand(2407);for($i=1;$i<=300;$i++){[$area,$road,$district,$lat,$lng,$mrt]=$areas[$i%count($areas)];$type=$types[$i%4];$bedrooms=1+($i%5);$floor=480+$bedrooms*180+($i%7)*37+($type==='Landed'?1800:0);$psf=520+($i%12)*115+($district==='D01'?850:0);$price=(int)(round($floor*$psf/10000)*10000);$title="{$area} {$names[$i%count($names)]}".($i>10?" {$i}":'');$slug=strtolower(preg_replace('/[^a-z0-9]+/i','-',$title));$image=$images[$i%count($images)];$insert->execute(['external_id'=>"SYN-{$i}",'agent_id'=>$agentIds[$i%count($agentIds)],'slug'=>trim($slug,'-'),'title'=>$title,'address'=>(10+$i)." {$road}",'district'=>$district,'property_type'=>$type,'tenure'=>$tenures[$i%4],'price'=>$price,'psf'=>$psf,'bedrooms'=>$bedrooms,'bathrooms'=>max(1,$bedrooms-1),'floor_area'=>$floor,'longitude'=>$lng+(mt_rand(-250,250)/10000),'latitude'=>$lat+(mt_rand(-180,180)/10000),'mrt_name'=>$mrt,'mrt_distance'=>100+($i*47)%1200,'image_url'=>$image,'images'=>json_encode([$image,$images[($i+1)%6],$images[($i+2)%6]]),'amenities'=>json_encode(['Pool','Gym','24h security','Near MRT','Covered parking']),'description'=>'A thoughtfully designed Singapore home with bright living spaces, practical storage and convenient access to transport, dining and everyday amenities.','featured'=>$i<=6?1:0,'listed_at'=>(new DateTimeImmutable())->modify("-{$i} hours")->format('Y-m-d H:i:s')]);$listingId=(int)$db->lastInsertId();if(!$listingId){$s=$db->prepare('SELECT id FROM listings WHERE external_id=?');$s->execute(["SYN-{$i}"]);$listingId=(int)$s->fetchColumn();}$tx=$db->prepare('INSERT INTO transactions(listing_id,transaction_month,price,psf) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE price=VALUES(price),psf=VALUES(psf)');for($m=11;$m>=0;$m--){$factor=.89+(11-$m)*.01;$tx->execute([$listingId,(new DateTimeImmutable("first day of -{$m} month"))->format('Y-m-d'),(int)($price*$factor),(int)($psf*$factor)]);}}
$user=$db->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),password_hash=VALUES(password_hash)');$user->execute(['Demo Explorer','demo@homescope.sg',password_hash('DemoPass123!',PASSWORD_ARGON2ID)]);echo "Seeded 300 synthetic listings and demo user.\n";
